    INCLUDE "config.inc"
; Elite (Amstrad CPC) MUSIQUEX.BIN, 128K build: the Blue Danube player of the stock build (generated by tools/disasm_stock.py; names from Fessor's reconstruction where known,
; otherwise sub_ (call target), loc_ (jump target), dat_ (data/variable reference)), assembled for the slot it has in the 64K game: 4096 bytes of flight-only code that the music
; replaces while the title screen runs. Here that slot is the same 4 KB of the code block in RAM bank 7 (&DF02, the tick at +&4A is loc_604A, which common2x.asm labels).
; bankInit loads this file into bank 7 over it; loadNotMusique loads NOTMUSIC.BIN (tools/build_dsk128.py writes the bytes of COMMON2X there) back before the docked loop runs.
; The title interrupt (dbIsr, hook in the overlay on bankInit, lasersights128.asm) calls MusicRun when bank 7 is visible and counts the ticks it has to skip while a far call hides it.
; The player never calls the firmware: the stock start and stop routines did (event registration at &BCD7/&BCDD), which would run the firmware on the game's stack in bank 7.
loc_604A equ 0xDF4C   ; generated: label of common2x
MUSIC_BASE equ loc_604A - 0x4A
 org MUSIC_BASE

    jr LAB_ram_6012
    db 0x18,0x00
; Music start: registers the event at &6167 with the firmware, then sets PSG register 7 (mixer) to &3F
SUB_ram_6004:
    ld a,0x07
    ld c,0x3F
    call SUB_ram_6139
    ret
LAB_ram_6012:
    ld hl,WORD_ram_6167
    ld de,MusicEventroutine
    ld bc,0x8100
    call 0xBCD7
    ld hl,MUSIQUEX6170
    ld (MUSIQUEX6161),hl
    ld (MUSIQUEX6163),hl
    ret
LAB_ram_6028:
    ld a,(BYTE_ram_615f)
    ld (BYTE_ram_6160),a
    jr LAB_ram_603a
LAB_ram_6030:
    call SUB_ram_6004
    jr LAB_ram_6041
LAB_ram_6035:
    ld hl,(MUSIQUEX6163)
    jr LAB_ram_6063
LAB_ram_603a:
    dec a
    ld (BYTE_ram_6160),a
    ld (MUSIQUEX6161),hl
LAB_ram_6041:
    pop ix
    pop iy
    pop hl
    pop de
    pop bc
    pop af
    ret
MusicEventroutine:
    push af
    push bc
    push de
    push hl
    push iy
    push ix
    ld a,(BYTE_ram_6160)                ; ticks left of the current note
    ld hl,(MUSIQUEX6161)                ; the score position
    cp 0x00
    jr nz,LAB_ram_603a
    ld a,0x07                           ; the note is over: mixer = tone on A, B and C, noise off, then read the next commands
    ld c,0x38
    call SUB_ram_6139
LAB_ram_6063:
    inc hl
    ld a,(hl)
    cp 0xF1
    jr z,LAB_ram_6093
    cp 0xF2
    jr z,LAB_ram_6098
    cp 0xF3
    jr z,LAB_ram_609d
    cp 0xF4
    jr z,LAB_ram_60a2
    cp 0xF6
    jr z,LAB_ram_60aa
    cp 0xAA
    jr z,LAB_ram_60b5
    cp 0xBB
    jr z,LAB_ram_60c9
    cp 0xCC
    jr z,LAB_ram_60d7
    cp 0xFF
    jr z,LAB_ram_6028
    cp 0xDD
    jr z,LAB_ram_6035
    cp 0xEE
    jr z,LAB_ram_6030
    jr LAB_ram_6063
LAB_ram_6093:
    call SUB_ram_60df
    jr LAB_ram_6063
LAB_ram_6098:
    call SUB_ram_60f6
    jr LAB_ram_6063
