    ld (BYTE_ram_6166),a
    jr LAB_ram_6063
LAB_ram_60d7:
    call SUB_ram_6159
    ld (BYTE_ram_615f),a
    jr LAB_ram_6063
; Music: sets PSG channel A period/volume (registers 0-1 and 8) from the track data, then the noise/envelope pair
SUB_ram_60df:
    ld a,0x01
    call SUB_ram_6137
    ld a,0x00
    call SUB_ram_6137
    ld a,(BYTE_ram_615c)
    ld c,a
    ld a,0x08
    call SUB_ram_6139
    call SUB_ram_6124
    ret
; Music: same as 60df for channel B (registers 2-3 and 9)
SUB_ram_60f6:
    ld a,0x03
    call SUB_ram_6137
    ld a,0x02
    call SUB_ram_6137
    ld a,(BYTE_ram_615d)
    ld c,a
    ld a,0x09
    call SUB_ram_6139
    call SUB_ram_6124
    ret
; Music: same as 60df for channel C (registers 4-5 and 10)
SUB_ram_610d:
    ld a,0x05
    call SUB_ram_6137
    ld a,0x04
    call SUB_ram_6137
    ld a,(BYTE_ram_615e)
    ld c,a
    ld a,0x0A
    call SUB_ram_6139
    call SUB_ram_6124
    ret
; Music: writes PSG registers 12 and 13 (envelope period and shape) from the track state
SUB_ram_6124:
    ld a,(BYTE_ram_6165)
    ld c,a
    ld a,0x0C
    call SUB_ram_6139
    ld a,(BYTE_ram_6166)
    ld c,a
    ld a,0x0D
    call SUB_ram_6139
    ret
; Music: advances the data pointer and writes the next byte to PSG register A
SUB_ram_6137:
    inc hl
    ld c,(hl)
; Writes value C to AY/PSG register A through the PPI ports, interrupts disabled (the stock routine ended in ei: here it only runs inside the ISR, which must stay uninterrupted)
SUB_ram_6139:
    di
    ld b,0xF4
    out (c),a
    ld b,0xF6
    in a,(c)
    or 0xC0
    out (c),a
    and 0x3F
    out (c),a
    ld b,0xF4
    out (c),c
    ld b,0xF6
    ld c,a
    or 0x80
    out (c),a
    out (c),c
    ret
; Music: advances the data pointer HL and returns the next data byte in A
SUB_ram_6159:
    inc hl
    ld a,(hl)
    ret
