; Called by the title interrupt (the hook in the overlay on bankInit) in a RAM configuration that shows bank 7 and the game stack, B = ticks to run: 1, plus the ticks that
; were skipped while a far call (the ship fill, bank 6 at &4000) hid this slot. The tune keeps its tempo, but the notes come in bursts after every fill.
MusicRun:
    ld a,b
    cp 25
    jr c,musicRunGo
    ld b,24                             ; after a very long skip: at most 24 ticks at once (the ISR must stay short)
musicRunGo:
    push bc
    call MusicEventroutine
    pop bc
    djnz musicRunGo
    ret
musicEnd:
    ASSERT musicEnd - MUSIC_BASE <= 0x1000, "the player does not fit the 4096 bytes of its slot"
    ds MUSIC_BASE + 0x1000 - $          ; the file keeps its 4096 bytes. (The 64K build kept the title ship selection in this zero tail; here it is resident code in commonxx.asm.)
